// Neon Loom: a maze of glowing cables built from Truchet tiles. Every
// square tile carries two quarter-circle arcs; random orientations join
// them into endless tangled loops. Comets of light race along the cables,
// always in a consistent direction. Tiles keep going dark, turning a
// quarter on a turntable and lighting up again, so the maze rewires
// itself as you watch.
// The silhouette of a second, larger loom drifts underneath.

#define TAU 6.28318531

mat2 rot(float a) {
  float c = cos(a);
  float s = sin(a);
  return mat2(c, -s, s, c);
}

vec3 palette(float t) {
  return 0.5 + 0.5 * cos(TAU * (t + vec3(0.0, 0.33, 0.67)));
}

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

// One loom layer. Returns colour in rgb and cable coverage in a; halo
// receives the light the cables throw on whatever lies below them.
vec4 loom(vec2 p, vec2 pan, float sc, float seed, float j, float hue, float px, out vec3 halo) {
  vec2 g = p * sc + pan;
  vec2 id = floor(g);
  vec2 q = fract(g) - 0.5;
  float pxs = px * sc;
  float h = hash(id + seed);
  float parity = mod(id.x + id.y, 2.0);

  // Each tile has its own clock. At the start of a cycle it goes dark,
  // turns a quarter, and lights up again.
  float clock = j * 0.1 * shuffle + h * 16.0;
  float f = fract(clock);
  float turning = smoothstep(0.03, 0.14, f);
  float lit = 1.0 - smoothstep(0.0, 0.03, f) * (1.0 - smoothstep(0.14, 0.18, f));
  float quarter = mod(floor(clock) + floor(h * 4.0), 4.0);
  vec2 l = rot(-(quarter + turning) * TAU * 0.25) * q;
  // While it turns, the tile is a disc that fits inside its square.
  float disc = mix(0.5, 0.72, lit);
  float inside = smoothstep(disc + pxs, disc - pxs, length(q));

  // Arcs around two opposite corners; take the nearer one.
  float sgn = l.x + l.y < 0.0 ? -1.0 : 1.0;
  vec2 v = l - sgn * 0.5;
  float across = abs(length(v) - 0.5);
  // Position along the arc: 0 where it meets the tile's vertical edge,
  // 1 at the horizontal edge.
  vec2 w = -sgn * v;
  float along = atan(w.x, w.y) / (TAU * 0.25);
  // On a checkerboard, light enters through vertical edges on one colour
  // and horizontal edges on the other, so it flows on across every joint.
  float flip = mod(parity + quarter + step(0.03, f), 2.0);
  along = mix(along, 1.0 - along, flip);

  float half_w = mix(0.1, 0.2, width);
  float x = across / half_w;
  float ax = pxs / half_w;
  float cover = smoothstep(1.0 + ax, 1.0 - ax, x) * inside;

  // Colour wanders slowly across the plane.
  float hh = hue + 0.12 * sin(p.x * 0.9 + p.y * 0.4) + 0.1 * cos(p.y * 0.8 - p.x * 0.3);
  // The flow, bent into chevrons that point down the cable.
  float s = along * 2.0 - j * 0.35 - x * 0.3;
  float as = pxs * 3.0;

  // A cable is three strands: a core carrying comets between two
  // steadily glowing rails.
  float fb = fract(s);
  float comet = fb * fb * smoothstep(1.0, 1.0 - as - 0.02, fb);
  vec3 core = palette(hh + floor(s) * 0.19) * (0.18 + 1.1 * comet) + 0.35 * comet * comet;
  core *= 0.4 + 0.6 * sqrt(max(1.0 - x * x / 0.16, 0.0));

  vec3 rail = palette(hh + 0.42) * (0.55 + 0.6 * comet);
  float rx = (x - 0.74) / 0.26;
  rail *= 0.35 + 0.65 * sqrt(max(1.0 - rx * rx, 0.0));

  float isCore = smoothstep(0.4 + ax, 0.4 - ax, x);
  float isRail = smoothstep(0.48 - ax, 0.48 + ax, x);
  vec3 col = core * isCore + rail * isRail;
  col *= mix(0.45, 1.0, lit);
  // The rim of the turntable shows while it is in use.
  float ring = (1.0 - lit) * smoothstep(0.012 + pxs, 0.012 - pxs, abs(length(q) - 0.47));
  col = mix(col, palette(hh + 0.7) * 0.8, ring);
  cover = max(cover, ring);

  float spill = exp(-max(across - half_w, 0.0) / 0.045) * inside;
  halo = palette(hh + 0.1) * spill * (0.2 + 0.5 * comet) * lit;
  return vec4(col, cover);
}

vec3 shader(vec2 uv, float time) {
  float j = drift + kick;
  vec2 p = (uv - 0.5) * vec2(resolution.x / resolution.y, 1.0) * 2.0;
  float px = 2.0 / resolution.y * (1.0 + bend);

  // Bend the plane: a bulge towards the viewer and slow rolling waves.
  p *= 1.0 + bend * 0.3 * dot(p, p);
  p += bend * 0.22 * vec2(sin(p.y * 1.7 + j * 0.07), sin(p.x * 1.3 - j * 0.05));
  p = rot(j * 0.013) * p;

  float hue = colour + j * 0.012;
  float sc = mix(1.5, 5.5, density * density);

  vec3 col = palette(hue + 0.6 + 0.15 * sin(p.x * 0.7 + p.y * 0.5)) * 0.05;

  vec3 halo;
  vec4 back = loom(p * 0.47, vec2(5.3, 2.1) + j * vec2(0.02, 0.012), sc, 7.0, j * 0.6, hue + 0.45, px * 0.47, halo);
  col = mix(col, palette(hue + 0.3) * 0.11, back.a);

  vec4 front = loom(p, j * vec2(0.06, 0.033), sc, 0.0, j, hue, px, halo);
  // The front cables sit above the back loom: shadow first, then glow.
  col *= 1.0 - 0.55 * length(halo);
  col += halo * 0.9;
  col = mix(col, front.rgb, front.a);

  col *= 1.0 - 0.35 * smoothstep(0.7, 1.9, length(uv - 0.5) * 2.0);
  return clamp(col, 0.0, 1.0);
}
